"""Independent synthetic pages for retained AVD DOM shapes; never use live data.

Markup is explicit, not generated by reflecting application selectors.
"""
import html
from urllib.parse import quote


def override_page(app, case):
    from .twins import document, field, select, button
    empty = case == 'empty'
    if app == 'APP00236324':
        return document('<iframe title="old ACE" style="display:none" src="/twin/MemberSearchVFPage_ACE?case=stale"></iframe>'
                        '<iframe title="ACE" style="width:1100px;height:650px" src="/twin/MemberSearchVFPage_ACE?case='+quote(case)+'"></iframe>')
    if app == 'APP00006838':
        successes = int(case) if case.isdigit() else 70
        rows = ''.join('<tr ng-repeat="batch in batches"><td>synthetic date</td><td>'+('SUCCESS' if i < successes else 'FAILED')+'</td><td></td><td>Disability</td></tr>' for i in range(0 if empty else 100))
        rows += '<tr ng-repeat="batch in batches"><td>synthetic date</td><td>FAILED</td><td></td><td>Other</td></tr>'
        body = '<select ng-model="system" disabled><option value="string:Disability">Disabled duplicate</option></select><select ng-model="system"><option value="other">Other</option></select><select ng-model="system" id="system" disabled></select><span ng-show="retrieving" id="loading">Loading</span><table id="batches" hidden>'+rows+'</table>'
        return document(body,"setTimeout(()=>{let s=document.getElementById('system');s.innerHTML='<option value=\"string:Disability\">Disability</option>';s.disabled=false;},150);setTimeout(()=>{document.getElementById('loading').style.display='none';document.getElementById('batches').hidden=false;},300);")
    if app == 'APP00005914':
        from .twins import login_page
        failed,total = ('nonnumeric','100') if case=='invalid' else ('0','0') if empty else (case if case.isdigit() else '10','100')
        body = '<a href="#/underwriting">Underwriting</a><div class="msg" style="display:none"><span>Loading Data</span></div><div is-open="vm.showSearchResults"><button><span>Failed</span><p class="h3">'+failed+'</p></button><button><span>Total</span><p class="h3">'+total+'</p></button></div>'
        return login_page(app,body,'/underwriting')
    if app not in {'APP00005761','APP00005212','APP00005953','APP00000069','APP00005184'}:
        return None
    reveal="document.getElementById('results').style.display='block'"
    if app=='APP00005761':
        summary='<span class="_groupField">DENTEST</span><span class="_accountField">1: ALOGIC</span>'
        body=select('searchType',[('NAME','Name')])+field('lastName')+field('firstName')+button('search','Search',reveal)+'<div id="results" style="display:none"><div id="row0"><span class="_lastName">'+('' if empty else 'TEST')+'</span><span class="_firstName">'+('OTHER' if case=='mismatch' else '' if empty else 'TEST')+'</span></div></div>'
    elif app=='APP00005212':
        summary='<div class="fset"><label>Group:</label><p style="width:200px" class="ng-binding">DENTEST</p></div><div class="fset"><label>Account:</label><p class="ng-binding">ALOGIC</p></div>'
        body=select('reportType',[('string:status','Status')])+'<label>Coverage Type</label>'+select('coverageType',[('all','All')])+field('start',name='startDate')+field('end',name='endDate')+button('viewReports','View Report',reveal)+'<div id="results" style="display:none"><div class="ui-grid-row"><div class="ui-grid-cell-contents">'+('' if empty else 'SYNTHETIC CLAIM')+'</div></div></div>'
    elif app=='APP00005953':
        summary='<div class="form-group col-sm-3 ng-binding"><label>Group Number</label><br>DENTEST</div><div class="form-group col-sm-3 ng-binding"><label>Account Number</label><br>ALOGIC</div>'
        checked=' checked' if case=='checked' else ''
        body='<input type="checkbox" id="decision" name="decision" value="All" ng-click="checkAll($event)"'+checked+' onclick="fetch(\'/twin/eoi-checkbox-toggle\',{method:\'POST\'})">'
        body+='<input type="button" value="Submit" onclick="if(document.getElementById(\'decision\').checked){'+reveal+'}"><table id="results" style="display:none"><tr><td data-title-text="Account">'+('' if empty else 'SYNTHETIC ACCOUNT')+'</td></tr></table>'
    elif app=='APP00000069':
        summary=''
        body='<img id="grp" src="/twin/pixel" alt="'+('Wrong' if case=='error' else 'Producers Corner')+'">'
    else:
        summary='<div class="form-group col-reg"><label for="group">Group Number</label><p class="ng-binding">'+('OTHER' if case=='error' else 'DENTEST')+'</p></div>'
        body=''
    angular=app in {'APP00005953','APP00005184'}
    controls=field('groupNumber',name='group')+select('accountNumber',[('0' if app=='APP00005184' else '1','1: ALOGIC')],**{'ng-model':'model.account'})+button('groupAccountContinue','Submit' if angular else 'Continue','completeContext()',type='button')
    # Modal blocks background clicks. Existing summary deliberately remains visible on reopen.
    modal='<div id="context" style="position:fixed;inset:0;background:#ddd;z-index:1000;padding:50px">'+controls+'</div>'
    import json
    body='<div id="page" hidden><button id="changeContext" onclick="openContext()">Change Group/Account</button>'+summary+body+'</div><div id="modalHost"></div>'
    script='''window.contextSubmits=0;
function openContext(){document.getElementById('modalHost').innerHTML=MODAL;}
function completeContext(){if(!document.getElementById('groupNumber').value.trim())return;
window.contextSubmits++;sessionStorage.setItem('synthetic_context','ready');
CLOSE;document.getElementById('page').hidden=false;}
if(CASE==='reopened'){document.getElementById('page').hidden=false;openContext();}
else if(sessionStorage.getItem('synthetic_context')==='ready'){document.getElementById('page').hidden=false;WARM;}
else openContext();
'''.replace('MODAL',json.dumps(modal)).replace('CASE',json.dumps(case)).replace('CLOSE',"document.getElementById('context').style.display='none'" if app=='APP00005212' else "document.getElementById('modalHost').innerHTML=''")
    script=script.replace('WARM',"openContext();document.getElementById('context').style.display='none'" if app=='APP00005212' else '')
    if app=='APP00005212':script+="location.hash='!/reports';"
    if app=='APP00005184':script+="location.hash='!/billing-information';"
    return document(body,script)


def teledent_frame(case, benefit=False):
    from .twins import document, field, button
    if benefit:return document('<p>'+('' if case=='empty' else 'Individual Deductible')+'</p>')
    if case=='stale':return document('<p>Old inactive frame</p>')
    # Two identical button IDs mirror the observed row-scoped second-button contract.
    body=field('SearchComponentSubscriberIdElement_ACE')+button('MemberSearchPageSearchButton_ACE','Search',"document.getElementById('results').hidden=false")
    body+='<table id="results" hidden><tr><td>'+button('collapseRowsArrow2_ACE','Expand',"document.getElementById('plan').hidden=false")+'</td></tr><tr id="plan" hidden><td>'+button('MemberSearchInnerTableSlelect_ACE','Other plan',"parent.wrongPlan=true")+'</td><td>PPO PASSIVE DENTAL [Dent]'+button('MemberSearchInnerTableSlelect_ACE','Select',"parent.showBenefit()")+'</td></tr></table>'
    # Retained switch_frame searches from default content, so benefit frame belongs to outer document.
    script="parent.showBenefit=()=>{let f=parent.document.createElement('iframe');f.id='iframeBenefitVendor_synthetic';f.src='/twin/benefit?case="+quote(case)+"';f.style='width:900px;height:400px';parent.document.body.appendChild(f);};"
    return document(body,script)
